#!/usr/bin/python
import os
import signal
import socket
import stat
import sys

BASE = os.path.dirname(os.path.abspath(__file__))
SOCKET_PATH = os.path.join(BASE, 'run/status.sock')
STATUS_PATH = os.path.join(BASE, 'status.txt')
listener = None
pidfile = None


def cleanup():
    global listener
    if listener is not None:
        try:
            listener.close()
        except socket.error:
            pass
    try:
        if os.path.exists(SOCKET_PATH):
            os.unlink(SOCKET_PATH)
    except OSError:
        pass
    if pidfile:
        try:
            os.unlink(pidfile)
        except OSError:
            pass


def stop_handler(signum, frame):
    cleanup()
    sys.exit(0)


def daemonize():
    if os.fork() > 0:
        os._exit(0)
    os.setsid()
    if os.fork() > 0:
        os._exit(0)
    os.chdir('/')
    nullfd = os.open('/dev/null', os.O_RDWR)
    os.dup2(nullfd, 0)
    os.dup2(nullfd, 1)
    os.dup2(nullfd, 2)
    if nullfd > 2:
        os.close(nullfd)


if '--daemon' in sys.argv:
    index = sys.argv.index('--daemon')
    if len(sys.argv) <= index + 1:
        sys.exit(2)
    pidfile = sys.argv[index + 1]
    daemonize()
    output = open(pidfile, 'w')
    output.write('%d\n' % os.getpid())
    output.close()

os.umask(007)
if os.path.lexists(SOCKET_PATH):
    mode = os.lstat(SOCKET_PATH).st_mode
    if not stat.S_ISSOCK(mode):
        sys.exit(3)
    os.unlink(SOCKET_PATH)

listener = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
listener.bind(SOCKET_PATH)
os.chmod(SOCKET_PATH, 0660)
listener.listen(5)
signal.signal(signal.SIGTERM, stop_handler)
signal.signal(signal.SIGINT, stop_handler)

while True:
    try:
        client, address = listener.accept()
    except socket.error:
        continue
    try:
        request = ''
        while len(request) < 1024 and '\n' not in request:
            chunk = client.recv(1024 - len(request))
            if not chunk:
                break
            request += chunk
        if request == 'STATUS\n':
            document = open(STATUS_PATH, 'rb')
            try:
                response = document.read()
            finally:
                document.close()
        else:
            response = 'ERROR\n'
        client.sendall(response)
    except (IOError, OSError, socket.error):
        pass
    try:
        client.close()
    except socket.error:
        pass
